'use strict';

/** @param {string} input */
function parse(input) {
  var values = /** @type {string[]} */ ([]);
  if (input.length === 0) {
    return values;
  }
  var parts = input.split('&');
  for (var i = 0; i < parts.length; i++) {
    var equals = parts[i].indexOf('=');
    if (equals >= 0) {
      values.push(parts[i].slice(equals + 1));
    }
  }
  return values;
}

/** @param {string[]} values */
function join(values) {
  return values.join('&');
}

exports.parse = parse;
exports.join = join;
